// VARA SAT 4.4.5's control codebook, generated by HF's codebook generator with SAT's differences.
// `sat_ctrl_lab.rs` checks it against a recorded link; the digest here pins the whole construction.
mod common;
use common::sha256_hex;
use xara_phy::call::call_hash;
use xara_phy::hf::ctrl::{Codebook, Fmt, Role, SAT_CODES, SAT_CONNECT_CODES, sat_family, sat_family_comb};
use xara_phy::hf::level::Bandwidth;

fn link() -> (Codebook, Codebook) {
    let (n0, n1) = (call_hash(b"N0CALL"), call_hash(b"N1CALL"));
    (Codebook::new_sat(n1, [n0, 0, 0, 0, 0], Role::Caller), Codebook::new_sat(n1, [n1, 0, 0, 0, 0], Role::Answerer))
}

fn codes() -> impl Iterator<Item = u32> {
    (1..=SAT_CODES).chain(SAT_CONNECT_CODES)
}

/// A code the caller sends must be the one the answerer listens for, and back, exactly where
/// that holds for HF 2300 (connect-request code 26 is seeded asymmetrically in both).
#[test]
fn caller_and_answerer_books_mirror_like_hf() {
    let (n0, n1) = (call_hash(b"N0CALL"), call_hash(b"N1CALL"));
    let hf = |role, h| Codebook::new(n1, [h, 0, 0, 0, 0], role, Bandwidth::Hz2300);
    let (hc, ha) = (hf(Role::Caller, n0), hf(Role::Answerer, n1));
    let (caller, answerer) = link();
    for f in Fmt::ALL {
        for c in 1..=SAT_CODES {
            let want = (hc.tx(f, c) == ha.rx(f, c), ha.tx(f, c) == hc.rx(f, c));
            let got = (caller.tx(f, c) == answerer.rx(f, c), answerer.tx(f, c) == caller.rx(f, c));
            assert_eq!(got, want, "code {c} fmt{f}");
        }
        for c in SAT_CONNECT_CODES {
            assert_eq!(caller.tx(f, c), answerer.rx(f, c), "code {c} fmt{f}");
        }
    }
}

#[test]
fn tones_stay_in_their_comb() {
    let (caller, _) = link();
    for f in Fmt::ALL {
        for c in codes() {
            let v = if SAT_CONNECT_CODES.contains(&c) { 2 } else { sat_family(c) };
            let (n, off) = sat_family_comb(v);
            // base n'·COMB + off (n' <= n), +1 on even symbols, + 2·(0..=6)
            let (lo, hi) = (off, n * 14 + off + 1 + 12);
            let w = caller.tx(f, c);
            assert!(!w.is_empty(), "code {c} fmt{f} empty");
            assert!(w.iter().flatten().all(|&t| (lo..=hi).contains(&t)), "code {c} fmt{f}: {w:?} outside {lo}..={hi}");
        }
    }
}

#[test]
fn differs_from_hf_2300_and_is_pinned() {
    let (n0, n1) = (call_hash(b"N0CALL"), call_hash(b"N1CALL"));
    let hf = Codebook::new(n1, [n0, 0, 0, 0, 0], Role::Caller, Bandwidth::Hz2300);
    let (sat, _) = link();
    assert!((1..=SAT_CODES).all(|c| sat.tx(Fmt::F0, c) != hf.tx(Fmt::F0, c)));
    let mut all = Vec::new();
    for f in Fmt::ALL {
        for c in codes() {
            all.extend(sat.tx(f, c).iter().flatten().map(|&t| t as u8));
            all.extend(sat.rx(f, c).iter().flatten().map(|&t| t as u8));
        }
    }
    assert_eq!(sha256_hex(&all), "5e3b0866ad582a2d691c8661950ba885414643c8385242d84f8068304b0bb41a");
}
